\begin{figure}[h]
\centering
\begin{tikzpicture}[
  auto,
  scale=1.0,
  result/.style={
    rectangle,
    draw=black,
    inner sep=1pt,
  },
  ]

  \node at (-5, 2) {\textbf{Upper Bounds}};

  \node[result] (generalizedwelfaregap) at (0, 2) {\begin{tabular}{c}
    \Cref{thm:main-upper} \\
    $\OLinear$ vs. $\OWelfare$ \\
    $O(n \log T)$ gap
  \end{tabular}};


  \draw[dashed] (-6, 1) -- (6, 1);


  \node at (-5, 0.5) {\textbf{Lower Bounds}};

  \node[result] (basecounterexample) at (-3, -1) {\begin{tabular}{c}
    \Cref{thm:main-lower} \\
    $\OLinear$ vs. $\OWelfare$ \\
    $\Omega(n \log T)$ gap with $m = 2$
  \end{tabular}};

  \node[result] (observedcounterexample) at (3, -1) {\begin{tabular}{c}
    \Cref{cor:two-outcome-linear} \\
    $\OMenu$ vs. $\OWelfare$ \\
    $\Omega(n \log T)$ gap with $m = 2$
  \end{tabular}};

  \node[result] (nonlinearitydisparity) at (-3, -4) {\begin{tabular}{c}
    \Cref{cor:nonlinearity-disparity} \\
    $\OLinear$ vs. $\OSingle$ \\
    $\Omega(n \log T)$ gap with $m = 4$
  \end{tabular}};

  \node[result] (infoispower) at (3, -4) {\begin{tabular}{c}
    \Cref{cor:info-is-power} \\
    $\OMenu$ vs. $\OTypeAware$ \\
    $\Omega(n \log T)$ gap with $m = 4$
  \end{tabular}};

  \node[result] at (0, -6) {\begin{tabular}{c}
    \Cref{lem:gap3v4} \\
    $\OSingle$ vs. $\OMenu$ \\
    $(2 - \epsilon)$ gap with $n = 3$
  \end{tabular}};

  \draw[->] (basecounterexample) -- (observedcounterexample) node[midway, above]
  {\Cref{lem:two-outcome-linear}};
  \draw[->] (basecounterexample) -- (nonlinearitydisparity) node[midway, left] {\Cref{lem:nonlinearity-disparity}};
  \draw[->] (observedcounterexample) -- (infoispower) node[midway, right] {\Cref{thm:info-is-power}};
\end{tikzpicture}
\caption{Proof road map of our upper and lower bound results between our various contract benchmarks.}
\label{fig:roadmap}
\end{figure}

